<script setup lang="ts">
import {reactive,ref} from 'vue';import {X} from 'lucide-vue-next';import type {Asset,AssetInput,CiModel} from '@/features/cmdb/types';import {validateAssetForm} from '@/features/cmdb/assetForm'
const props=defineProps<{asset?:Asset;models:CiModel[]}>();const emit=defineEmits<{close:[];save:[value:AssetInput]}>();const errors=ref<string[]>([]);const form=reactive<AssetInput>(props.asset?{id:props.asset.id,name:props.asset.name,type:props.asset.type,status:props.asset.status,ip:props.asset.ip,environment:props.asset.environment,projectGroup:props.asset.projectGroup,owner:props.asset.owner,location:props.asset.location,source:props.asset.source,tags:[...props.asset.tags]}:{id:'',name:'',type:'physical-server',status:'online',ip:'',environment:'生产',projectGroup:'',owner:'',location:'',source:'manual',tags:[]});const tagsText=ref(form.tags.join('|'));function submit(){form.tags=tagsText.value.split('|').map(v=>v.trim()).filter(Boolean);errors.value=validateAssetForm(form);if(!errors.value.length)emit('save',{...form,tags:[...form.tags]})}
</script>
<template><div class="modal-backdrop"><form class="asset-editor" @submit.prevent="submit"><header><div><span>{{asset?'编辑资产':'新增资产'}}</span><h2>{{asset?.name||'登记新的配置项'}}</h2></div><button type="button" aria-label="关闭" @click="emit('close')"><X/></button></header><div class="editor-grid"><label><span>资产编号 *</span><input v-model="form.id" :disabled="Boolean(asset)"></label><label><span>资产名称 *</span><input v-model="form.name"></label><label><span>CI 模型 *</span><select v-model="form.type" :disabled="Boolean(asset)"><option v-for="model in models" :key="model.code" :value="model.code">{{model.name}}</option></select></label><label><span>状态</span><select v-model="form.status"><option value="online">在线</option><option value="warning">异常</option><option value="offline">离线</option></select></label><label><span>IP 地址</span><input v-model="form.ip"></label><label><span>环境</span><select v-model="form.environment"><option>生产</option><option>测试</option><option>开发</option></select></label><label><span>项目组 *</span><input v-model="form.projectGroup"></label><label><span>负责人 *</span><input v-model="form.owner"></label><label class="wide"><span>位置</span><input v-model="form.location"></label><label class="wide"><span>标签（使用 | 分隔）</span><input v-model="tagsText"></label></div><div v-if="errors.length" class="form-errors"><span v-for="error in errors" :key="error">{{error}}</span></div><footer><button type="button" @click="emit('close')">取消</button><button class="primary" type="submit">保存资产</button></footer></form></div></template>
